          />
          <button type="button" data-testid="claim-split" (click)="split(c)">Split</button>
          <label [for]="'claim-reassign-to-' + c.id">Move to</label>
          <select
            [id]="'claim-reassign-to-' + c.id"
            data-testid="claim-reassign-to"
